create table if not exists public.access_members (
  id bigint generated by default as identity primary key,
  email text unique not null check (email = lower(email)),
  is_admin boolean not null default false,
  status text not null default 'approved' check (status in ('pending', 'approved', 'rejected', 'revoked')),
  created_at timestamptz not null default now()
);
alter table public.access_members add column if not exists status text not null default 'approved';
alter table public.access_members drop constraint if exists access_members_status_check;
alter table public.access_members add constraint access_members_status_check check (status in ('pending', 'approved', 'rejected', 'revoked'));

create table if not exists public.articles (
  id bigint generated by default as identity primary key,
  section text not null default 'theory' check (section in ('theory', 'practice')),
  course text not null default 'manual' check (course in ('manual', 'automation')),
  category text not null,
  title text not null,
  description text not null,
  content text not null,
  read_time text not null default '',
  color text not null default 'purple',
  icon text not null default '◉',
  image_url text,
  status text not null default 'published' check (status in ('draft', 'published')),
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.articles add column if not exists course text not null default 'manual';
alter table public.articles add column if not exists tags text not null default '';
alter table public.articles drop constraint if exists articles_course_check;
alter table public.articles add constraint articles_course_check check (course in ('manual', 'automation'));

create table if not exists public.access_requests (
  id bigint generated by default as identity primary key,
  name text not null,
  email text not null,
  message text not null,
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  reviewed_by uuid references auth.users(id),
  reviewed_at timestamptz,
  created_at timestamptz not null default now()
);

alter table public.articles add column if not exists section text not null default 'theory';
alter table public.articles add column if not exists status text not null default 'published';
alter table public.articles add column if not exists sort_order integer not null default 0;
alter table public.articles add column if not exists updated_at timestamptz not null default now();
alter table public.articles drop constraint if exists articles_section_check;
alter table public.articles add constraint articles_section_check check (section in ('theory', 'practice'));
alter table public.articles drop constraint if exists articles_status_check;
alter table public.articles add constraint articles_status_check check (status in ('draft', 'published'));
alter table public.articles drop constraint if exists articles_status_check;
alter table public.articles add constraint articles_status_check check (status in ('draft', 'published', 'archived'));
alter table public.articles add column if not exists slug text;
alter table public.articles add column if not exists module text not null default 'Основы';
alter table public.articles add column if not exists level text not null default 'beginner';
alter table public.articles add column if not exists estimated_minutes integer not null default 10;
alter table public.articles add column if not exists metadata jsonb not null default '{}'::jsonb;
alter table public.articles add column if not exists related_article_ids bigint[] not null default '{}';
alter table public.articles add column if not exists course_key text not null default 'manual-qa';
alter table public.articles add column if not exists content_json jsonb not null default '{}'::jsonb;
alter table public.articles drop constraint if exists articles_course_key_check;
alter table public.articles add constraint articles_course_key_check check (course_key in ('manual-qa', 'automation-python', 'standalone'));
create unique index if not exists articles_slug_unique on public.articles (slug) where slug is not null;
alter table public.articles drop constraint if exists articles_level_check;
alter table public.articles add constraint articles_level_check check (level in ('beginner', 'intermediate', 'advanced'));

create table if not exists public.article_versions (
  id bigint generated by default as identity primary key,
  article_id bigint not null references public.articles(id) on delete cascade,
  title text not null,
  description text not null,
  content text not null,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid not null references auth.users(id),
  created_at timestamptz not null default now()
);

create table if not exists public.media_assets (
  id bigint generated by default as identity primary key,
  storage_path text not null unique,
  file_name text not null,
  mime_type text not null,
  file_size integer not null,
  alt_text text not null default '',
  caption text not null default '',
  created_by uuid not null references auth.users(id),
  created_at timestamptz not null default now()
);

create table if not exists public.audit_logs (
  id bigint generated by default as identity primary key,
  actor_id uuid not null references auth.users(id),
  action text not null,
  entity_type text not null,
  entity_id text not null,
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  email text,
  display_name text not null default '',
  avatar_url text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.article_progress (
  user_id uuid not null references auth.users(id) on delete cascade,
  article_id bigint not null references public.articles(id) on delete cascade,
  completed_at timestamptz not null default now(),
  primary key (user_id, article_id)
);

create table if not exists public.quiz_questions (
  id bigint generated by default as identity primary key,
  article_id bigint not null references public.articles(id) on delete cascade,
  question text not null,
  options jsonb not null default '[]'::jsonb,
  correct_option integer not null default 0,
  explanation text not null default '',
  sort_order integer not null default 0
);

