select a.id, 'Что проверяет функциональное тестирование?', '["Заявленное поведение системы","Только скорость ответа","Только внешний вид"]'::jsonb, 0, 'Функциональные проверки сопоставляют поведение системы с требованиями.', 10
from public.articles a
where a.title = 'Виды тестирования'
  and not exists (select 1 from public.quiz_questions q where q.article_id = a.id);

insert into public.quiz_questions (article_id, question, options, correct_option, explanation, sort_order)
select a.id, 'Что является главной целью тестирования?', '["Доказать отсутствие всех дефектов","Получить информацию о качестве и снизить риски","Проверить только код разработчика"]'::jsonb, 1, 'Тестирование даёт команде информацию для решений и помогает управлять рисками.', 10
from public.articles a
