insert into public.quiz_questions (article_id, question, options, correct_option, explanation, sort_order)
select a.id, 'Какие значения полезны для диапазона от 18 до 65?', '["Только 18 и 65","17, 18, 19, 64, 65 и 66","Только 30"]'::jsonb, 1, 'Граничные значения включают сами границы, соседей и представителей классов.', 10
from public.articles a
where a.title = 'Техники тест-дизайна: как выбирать проверки'
  and not exists (select 1 from public.quiz_questions q where q.article_id = a.id);

insert into public.quiz_questions (article_id, question, options, correct_option, explanation, sort_order)
select a.id, 'Что означает priority в баг-репорте?', '["Влияние дефекта на систему","Очередность исправления с учётом бизнеса и рисков","Количество шагов воспроизведения"]'::jsonb, 1, 'Priority показывает срочность и порядок работы, а severity — влияние дефекта.', 10
from public.articles a
where a.title = 'Приоритет и серьёзность дефекта'
  and not exists (select 1 from public.quiz_questions q where q.article_id = a.id);

create or replace function public.is_admin()
returns boolean language sql security definer set search_path = public
as $$ select exists (select 1 from public.access_members where email = lower(auth.email()) and is_admin and status = 'approved'); $$;

create or replace function public.has_access()
returns boolean language sql security definer set search_path = public
as $$ select exists (select 1 from public.access_members where email = lower(auth.email()) and status = 'approved'); $$;

alter table public.access_members enable row level security;
alter table public.articles enable row level security;
alter table public.profiles enable row level security;
alter table public.article_progress enable row level security;
alter table public.quiz_questions enable row level security;
alter table public.article_versions enable row level security;
alter table public.media_assets enable row level security;
alter table public.audit_logs enable row level security;

drop policy if exists "members can read own access" on public.access_members;
create policy "members can read own access" on public.access_members for select to authenticated
using (email = lower(auth.email()) or public.is_admin());
drop policy if exists "admins manage members" on public.access_members;
create policy "admins manage members" on public.access_members for all to authenticated
using (public.is_admin()) with check (public.is_admin());

alter table public.access_requests enable row level security;
drop policy if exists "guests can create access requests" on public.access_requests;
create policy "guests can create access requests" on public.access_requests for insert to anon, authenticated
with check (status = 'pending');
drop policy if exists "admins manage access requests" on public.access_requests;
create policy "admins manage access requests" on public.access_requests for all to authenticated
using (public.is_admin()) with check (public.is_admin());

drop policy if exists "members read articles" on public.articles;
create policy "members read articles" on public.articles for select to authenticated
using (public.is_admin() or (public.has_access() and status = 'published'));
drop policy if exists "admins manage articles" on public.articles;
create policy "admins manage articles" on public.articles for all to authenticated
using (public.is_admin()) with check (public.is_admin());

drop policy if exists "admins manage article versions" on public.article_versions;
create policy "admins manage article versions" on public.article_versions for all to authenticated
using (public.is_admin()) with check (public.is_admin());
drop policy if exists "admins manage media assets" on public.media_assets;
create policy "admins manage media assets" on public.media_assets for all to authenticated
using (public.is_admin()) with check (public.is_admin());
drop policy if exists "admins read audit logs" on public.audit_logs;
create policy "admins read audit logs" on public.audit_logs for select to authenticated
using (public.is_admin());
drop policy if exists "admins create audit logs" on public.audit_logs;
create policy "admins create audit logs" on public.audit_logs for insert to authenticated
with check (public.is_admin() and actor_id = auth.uid());

drop policy if exists "users manage own profile" on public.profiles;
create policy "users manage own profile" on public.profiles for all to authenticated
using (id = auth.uid() or public.is_admin())
with check (id = auth.uid() or public.is_admin());

drop policy if exists "users manage own progress" on public.article_progress;
create policy "users manage own progress" on public.article_progress for all to authenticated
using (user_id = auth.uid() or public.is_admin())
with check (user_id = auth.uid() or public.is_admin());

drop policy if exists "members read quizzes" on public.quiz_questions;
create policy "members read quizzes" on public.quiz_questions for select to authenticated
using (public.is_admin() or public.has_access());
drop policy if exists "admins manage quizzes" on public.quiz_questions;
create policy "admins manage quizzes" on public.quiz_questions for all to authenticated
using (public.is_admin()) with check (public.is_admin());

-- Public URLs are safe because writes are restricted to admins / the owner.
insert into storage.buckets (id, name, public)
values ('article-images', 'article-images', false), ('avatars', 'avatars', false)
on conflict (id) do update set public = excluded.public;

drop policy if exists "public can view QA Base images" on storage.objects;
create policy "members can view private images" on storage.objects for select to authenticated
using (bucket_id in ('article-images', 'avatars') and (public.is_admin() or public.has_access()));
drop policy if exists "admins upload article images" on storage.objects;
create policy "admins upload article images" on storage.objects for insert to authenticated
with check (bucket_id = 'article-images' and public.is_admin());
drop policy if exists "admins update article images" on storage.objects;
create policy "admins update article images" on storage.objects for update to authenticated
using (bucket_id = 'article-images' and public.is_admin());
drop policy if exists "admins delete article images" on storage.objects;
create policy "admins delete article images" on storage.objects for delete to authenticated
using (bucket_id = 'article-images' and public.is_admin());
drop policy if exists "users upload own avatar" on storage.objects;
create policy "users upload own avatar" on storage.objects for insert to authenticated
with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);
drop policy if exists "users update own avatar" on storage.objects;
create policy "users update own avatar" on storage.objects for update to authenticated
using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);

-- Initial Automation QA — Python track. Content remains protected by the articles RLS policy.
insert into public.articles (course, course_key, section, category, title, description, content, read_time, status, sort_order, tags)
select seed.course, 'automation-python', 'theory', seed.category, seed.title, seed.description, seed.content, seed.read_time, 'published', seed.sort_order, seed.tags
from (values
  ('automation', 'Основы автоматизации', 'Что такое автоматизация тестирования', 'Когда автоматизация помогает QA и почему она не заменяет исследовательское тестирование.',
   '<h3>Определение</h3><p><strong>Автоматизация тестирования (test automation)</strong> — использование программ и скриптов для выполнения проверок и обработки результатов с минимальным ручным вмешательством.</p><h3>Простыми словами</h3><p>Если один и тот же стабильный сценарий приходится повторять десятки раз, его можно описать кодом. Но автоматизировать стоит не всё: исследование нового продукта, визуальную оценку и неоднозначные проверки часто эффективнее выполнять вручную.</p><h3>Пример</h3><p>Smoke-проверка авторизации может запускаться после каждого деплоя и быстро сообщать команде, что основная функция доступна.</p><h3>Практика</h3><p>Выбери три сценария интернет-магазина и раздели их на подходящие для UI-автоматизации, API-автоматизации и ручного exploratory-тестирования.</p><h3>Что запомнить</h3><ul><li>Автоматизация — это разработка программного кода.</li><li>Стабильность и диагностичность важнее количества тестов.</li><li>Автотест проверяет только то, что в него заложено.</li></ul>',
   '12 мин', 10, 'automation, test automation, automation pyramid'),
  ('automation', 'Python с нуля', 'Python для тестировщика: переменные, условия и функции', 'Минимальная база Python, необходимая для чтения и написания простых автотестов.',
   '<h3>Базовые конструкции</h3><p>Переменная хранит значение: <code>age = 21</code>. Условие выбирает ветку: <code>if age &gt;= 18:</code>. Функция объединяет повторяемую логику и возвращает результат.</p><pre><code>def is_adult(age):\n    return age &gt;= 18\n\nassert is_adult(21) is True\nassert is_adult(16) is False</code></pre><h3>Почему это важно QA</h3><p>Даже при использовании готового фреймворка нужно понимать типы данных, области видимости, циклы и исключения, иначе отладка теста превращается в угадывание.</p><h3>Типичные ошибки</h3><ul><li>Сравнивать строку и число без преобразования.</li><li>Писать длинные функции без понятного результата.</li><li>Скрывать ошибки широким <code>except Exception</code>.</li></ul><h3>Практика</h3><p>Напиши функцию проверки пароля: от 8 до 32 символов, есть цифра и отсутствуют пробелы. Добавь проверки для валидного и невалидного ввода.</p>',
   '18 мин', 20, 'python, functions, assertions'),
  ('automation', 'Pytest', 'Pytest: тесты, assertions и fixtures', 'Как организовать автоматические проверки на Python с помощью pytest.',
   '<h3>Минимальный тест</h3><pre><code>def test_total():\n    assert 2 + 3 == 5</code></pre><p>Pytest находит файлы и функции по соглашениям, запускает проверки и показывает место падения. <strong>Assertion</strong> сравнивает фактический результат с ожидаемым.</p><h3>Fixtures</h3><p>Fixture подготавливает повторяемое окружение или данные. Это лучше, чем копировать setup в каждый тест.</p><pre><code>import pytest\n\n@pytest.fixture\ndef user():\n    return {\"role\": \"qa\"}\n\ndef test_user_role(user):\n    assert user[\"role\"] == \"qa\"</code></pre><h3>Практика</h3><p>Создай fixture с тестовым пользователем и параметризуй тест для трёх ролей. Укажи, какой результат ожидается для каждой роли.</p>',
   '20 мин', 30, 'pytest, fixtures, assertions'),
  ('automation', 'Браузерная автоматизация', 'Playwright на Python: локаторы и web-first assertions', 'Надёжная проверка веб-интерфейса с ожиданием состояния, а не фиксированными sleep.',
   '<h3>Пример</h3><pre><code>from playwright.sync_api import Page, expect\n\ndef test_login(page: Page):\n    page.goto(\"https://example.com/login\")\n    page.get_by_label(\"Email\").fill(\"qa@example.com\")\n    page.get_by_label(\"Пароль\").fill(\"secret\")\n    page.get_by_role(\"button\", name=\"Войти\").click()\n    expect(page.get_by_text(\"Личный кабинет\")).to_be_visible()</code></pre><h3>Почему locator</h3><p>Локатор должен описывать смысл элемента и переживать небольшие изменения вёрстки. Роли и доступные имена часто устойчивее длинного XPath.</p><h3>Ожидания</h3><p>Web-first assertion ждёт нужное состояние элемента. Фиксированный <code>sleep</code> замедляет тест и создаёт flaky-поведение.</p><h3>Практика</h3><p>Напиши тест поиска товара: введи запрос, дождись карточки результата и проверь заголовок и цену.</p>',
   '24 мин', 40, 'python, playwright, locators'),
  ('automation', 'API automation', 'API-автоматизация на Python с requests', 'Как отправлять HTTP-запросы и проверять статус, JSON и негативные сценарии.',
   '<h3>Пример</h3><pre><code>import requests\n\ndef test_create_user():\n    response = requests.post(\n        \"https://api.example.com/users\",\n        json={\"name\": \"Alex\", \"email\": \"alex@example.com\"},\n        timeout=10,\n    )\n    assert response.status_code == 201\n    assert response.json()[\"email\"] == \"alex@example.com\"</code></pre><h3>Что проверять</h3><p>Проверяй статус-код, структуру и типы JSON, обязательные поля, headers, время ответа, авторизацию и ошибки на некорректные данные.</p><h3>Практика</h3><p>Добавь тесты для пустого email, дубликата пользователя и запроса без токена. Для каждого сценария зафиксируй ожидаемый status code и сообщение.</p>',
   '22 мин', 50, 'python, requests, api'),
  ('automation', 'Архитектура', 'Page Object Model в Python', 'Как отделить описание страницы от сценариев теста и уменьшить дублирование.',
   '<h3>Идея</h3><p><strong>Page Object Model</strong> инкапсулирует локаторы и действия конкретной страницы в отдельном классе. Тест остаётся сценарием, а детали UI живут в объекте страницы.</p><pre><code>class LoginPage:\n    def __init__(self, page):\n        self.page = page\n\n    def login(self, email, password):\n        self.page.get_by_label(\"Email\").fill(email)\n        self.page.get_by_label(\"Пароль\").fill(password)\n        self.page.get_by_role(\"button\", name=\"Войти\").click()</code></pre><h3>Границы подхода</h3><p>Page Object не должен превращаться в класс со всей бизнес-логикой приложения. Сохраняй короткие действия и понятные assertions на уровне теста.</p><h3>Практика</h3><p>Вынеси страницу корзины в объект с методами add_item, remove_item и total. Напиши отдельный тест на итоговую сумму.</p>',
   '20 мин', 60, 'python, oop, page object model'),
  ('automation', 'Качество автотестов', 'Flaky tests: причины и диагностика', 'Почему тест иногда проходит, а иногда падает, и как устранить нестабильность.',
   '<h3>Причины</h3><ul><li>гонка между тестом и загрузкой интерфейса;</li><li>общие изменяемые данные;</li><li>зависимость тестов от порядка запуска;</li><li>нестабильная сеть или внешний сервис;</li><li>неуникальные локаторы.</li></ul><h3>Подход</h3><p>Сначала сохрани лог, screenshot/trace и окружение. Затем воспроизведи проблему отдельно, проверь ожидания и изоляцию данных. Слепой retry скрывает симптом и ухудшает доверие к suite.</p><h3>Практика</h3><p>Возьми нестабильный сценарий и составь гипотезы по категориям: timing, data, environment, locator. Для каждой укажи проверку и исправление.</p>',
   '16 мин', 70, 'flaky tests, waits, debugging'),
  ('automation', 'CI/CD', 'Запуск pytest в GitHub Actions', 'Как запускать автотесты в pipeline и сохранять результат для команды.',
   '<h3>Минимальный pipeline</h3><pre><code>name: tests\non: [push]\njobs:\n  pytest:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-python@v5\n        with:\n          python-version: \"3.12\"\n      - run: pip install -r requirements.txt\n      - run: pytest -q</code></pre><h3>Безопасность</h3><p>Токены и пароли хранятся в Secrets, а не в YAML и не в логах. В pipeline полезно разделять быстрый smoke и полный набор.</p><h3>Практика</h3><p>Добавь workflow для pytest, сохрани JUnit-отчёт как artifact и опиши, какие тесты должны блокировать merge.</p>',
   '18 мин', 80, 'python, pytest, ci/cd')
) as seed(course, category, title, description, content, read_time, sort_order, tags)
where not exists (
  select 1 from public.articles existing where existing.course = seed.course and existing.title = seed.title
);
